  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic csx,
  output logic dcx,
  output logic wrx,
  output logic rdx,
  output logic [15:0] d_o,
  output logic d_oe,
  input logic [15:0] d_i,
  output logic scl,
  output logic sda_o,
  output logic sda_oe,
  input logic sda_i
);
  localparam logic [31:0] ID_VALUE = 32'h44420200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [8:0] hit;
