    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd9) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [1:0]    c_cfg_type;
  logic          c_cfg_w16;
  logic [3:0]    c_cfg_tw;
  logic [3:0]    c_cfg_tr;
  logic [1:0]    c_cfg_dummy;
  logic          c_op_valid;
  logic          c_op_ready;
  logic          c_op_dc;
  logic          c_op_rd;
  logic          c_op_last;
  logic [15:0]   c_op_data;
  logic          c_rd_valid;
  logic [15:0]   c_rd_data;
  logic          c_busy;
  MIPI_DBI__Display_Bus_Interface__top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_type(c_cfg_type),
    .cfg_w16(c_cfg_w16),
    .cfg_tw(c_cfg_tw),
    .cfg_tr(c_cfg_tr),
    .cfg_dummy(c_cfg_dummy),
    .op_valid(c_op_valid),
    .op_ready(c_op_ready),
    .op_dc(c_op_dc),
    .op_rd(c_op_rd),
    .op_last(c_op_last),
    .op_data(c_op_data),
    .rd_valid(c_rd_valid),
    .rd_data(c_rd_data),
    .busy(c_busy),
