    .dcx(dcx),
    .wrx(wrx),
    .rdx(rdx),
    .d_o(d_o),
    .d_oe(d_oe),
    .d_i(d_i),
    .scl(scl),
    .sda_o(sda_o),
    .sda_oe(sda_oe),
    .sda_i(sda_i)
  );

  // ---------------- registers ----------------
  logic [3:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [12:0] r_CFG;   // 12'h014 CFG
  logic [18:0] h_OP;   // 12'h018 OP holding register
  logic [15:0] h_RD;   // 12'h01C RD holding register
  logic full_OP;
  logic avail_RD;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 13'hA11;
      h_OP <= '0;
      h_RD <= '0;
      full_OP <= 1'b0;
      avail_RD <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[3:0] & wmask[3:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[12:0]) | (PWDATA[12:0] & wmask[12:0]);
      if (wr && hit[6] && !full_OP) h_OP <= (h_OP & ~wmask[18:0]) | (PWDATA[18:0] & wmask[18:0]);
      if (wr && hit[6] && !full_OP) full_OP <= 1'b1;
      else if (full_OP && c_op_ready) full_OP <= 1'b0;
      if (c_rd_valid && (!avail_RD || (rd && hit[7]))) begin
        h_RD[15:0] <= c_rd_data[15:0];
        avail_RD <= 1'b1;
      end else if (rd && hit[7]) avail_RD <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_type = r_CFG[1:0];
  assign c_cfg_w16 = r_CFG[2:2];
  assign c_cfg_tw = r_CFG[6:3];
  assign c_cfg_tr = r_CFG[10:7];
  assign c_cfg_dummy = r_CFG[12:11];
  assign c_op_data[15:0] = h_OP[15:0];
  assign c_op_dc = h_OP[16:16];
  assign c_op_rd = h_OP[17:17];
  assign c_op_last = h_OP[18:18];
  assign c_op_valid = full_OP;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = full_OP & c_op_ready;
    irq_set[1] = wr & (hit[6]) & full_OP;
    irq_set[2] = c_rd_valid & (~avail_RD | (rd & hit[7]));
    irq_set[3] = c_rd_valid & avail_RD & ~(rd & hit[7]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RD, full_OP};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
